保存为 recovery.mjs，运行 node recovery.mjs，无依赖。程序实际计算两次 k 并回放策略，不调用外部服务。输入上限只是教学防误用，不是性能预算。

```js
/**
 * @file Fit a toy imitation policy and audit recovery after disturbances.
 * @author liliwei
 * @date 2026-11-13
 * @LastEditors liliwei
 * @LastEditTime 2026-11-13
 */
/** @param {number} x Raw action. @returns {number} Action limited to one unit. */
export function clip(x) { return Math.max(-1, Math.min(1, x)); }
/** @param {number} e Lateral error. @returns {number} Expert correction. */
export function expert(e) { return Math.abs(e) <= 0.25 ? 0 : clip(-e); }
/** @param {Array<{e:number,a:number}>} rows Expert labels. @returns {number} Least-squares gain. */
export function fit(rows) {
  if (!Array.isArray(rows) || !rows.length || rows.length > 10000) throw Error('Invalid rows');
  let xy = 0, xx = 0;
  for (const r of rows) {
    if (!r || !Number.isFinite(r.e) || Math.abs(r.e) > 100 ||
        !Number.isFinite(r.a) || Math.abs(r.a) > 1) throw Error('Invalid label');
    xy += r.e * r.a; xx += r.e * r.e;
  }
  return xx === 0 ? 0 : -xy / xx;
}
/** @param {number} k Learned gain. @returns {(e:number)=>number} Frozen policy. */
export function policy(k) {
  if (!Number.isFinite(k)) throw Error('Invalid gain');
  return e => clip(-k * e);
}
/** @param {Function} act Controller. @param {number[]} pushes Pre-action disturbances.
 * @returns {Array<{e:number,a:number,next:number}>} Actual controller trajectory. */
export function rollout(act, pushes) {
  if (typeof act !== 'function' || !Array.isArray(pushes) ||
      !pushes.length || pushes.length > 1000) throw Error('Invalid rollout');
  let x = 0; const trace = [];
  for (const push of pushes) {
    if (!Number.isFinite(push) || Math.abs(push) > 10) throw Error('Invalid push');
    const e = x + push;
    if (Math.abs(e) > 100) throw Error('State out of range');
    const a = act(e);
    if (!Number.isFinite(a) || Math.abs(a) > 1) throw Error('Invalid action');
    x = e + a; trace.push({e, a, next:x});
  }
  return trace;
}
/** @param {number} value Impulse. @param {number} n Steps. @returns {number[]} Push at index 2. */
export function kick(value, n = 8) { return Array.from({length:n}, (_, t) => t === 2 ? value : 0); }
const demos = Array.from({length:6}, () => ({e:0, a:0}));
export const k0 = fit(demos);
// Expert labels the learner's visited states; it does not execute these actions.
const visited = [-2, 2].flatMap(v => rollout(policy(k0), kick(v, 6)));
const labeled = visited.map(r => ({e:r.e, a:expert(r.e)}));
export const k1 = fit([...demos, ...labeled]);
export const cases = [-1.5, -1, -0.5, 0.5, 1, 1.5].map(v => kick(v));
/** @param {Function} act Controller. @param {number[][]} inputs Episodes.
 * @returns {object} Endpoint and post-action error metrics. */
export function score(act, inputs) {
  const runs = inputs.map(p => rollout(act, p));
  const errors = runs.flatMap(r => r.map(s => Math.abs(s.next)));
  return {episodes:runs.length, recovered:runs.filter(r => Math.abs(r.at(-1).next) <= 0.25).length,
    meanError:errors.reduce((a,b) => a+b, 0)/errors.length,
    maxFinalError:Math.max(...runs.map(r => Math.abs(r.at(-1).next)))};
}
console.log(JSON.stringify({k0, k1, trainingRows:demos.length+labeled.length,
  before:score(policy(k0),cases), after:score(policy(k1),cases),
  wind:score(policy(k1),[Array(8).fill(0.5)]), expertWind:score(expert,[Array(8).fill(0.5)])}));
```

labeled 使用的是 expert(r.e)，不是 r.a；回放的下一步则来自学习器实际动作。这两个字段混淆，就会把学习器自己的错误重复当答案。这里保留重复访问作为样本权重；生产数据中重复停滞可能淹没少见状态，需要记录采样与加权方式，并重新验收。
